import binascii
import io
import gzip


def task_func(compressed_hex):
    """
    Decode a gzip-compressed hexadecimal string and return the UTF-8 text.

    Parameters:
        compressed_hex (str | bytes): Hexadecimal string representing gzip-compressed bytes.

    Returns:
        str: Decoded UTF-8 string, or an error message if decoding fails.
    """
    try:
        if compressed_hex is None:
            return "Error: input is None"

        if isinstance(compressed_hex, bytes):
            compressed_hex = compressed_hex.decode("utf-8", errors="strict")
        elif not isinstance(compressed_hex, str):
            compressed_hex = str(compressed_hex)

        hex_str = "".join(compressed_hex.split())
        if not hex_str:
            return "Error: input is empty"

        compressed_bytes = binascii.unhexlify(hex_str)

        # Use gzip with an in-memory buffer for robust decompression.
        with gzip.GzipFile(fileobj=io.BytesIO(compressed_bytes), mode="rb") as gz:
            decompressed_bytes = gz.read()

        return decompressed_bytes.decode("utf-8")

    except (binascii.Error, ValueError) as e:
        return f"Error: invalid hexadecimal or gzip data ({e})"
    except UnicodeDecodeError as e:
        return f"Error: decompressed data is not valid UTF-8 ({e})"
    except OSError as e:
        return f"Error: gzip decompression failed ({e})"
    except Exception as e:
        return f"Error: unexpected failure ({e})"
